  "inlineSchema": "// ---------------------------------------------------------------------------\n// Catalog\n//\n// ProductType      - the big group. It decides the size chart, how the item is\n//                    shown in the store and which categories are allowed.\n// ProductCategory  - the kind of item inside a group (hoodie, jeans, sneakers).\n//                    Which category belongs to which type is checked in\n//                    src/config/catalog.config.ts (a database enum cannot do it).\n// ---------------------------------------------------------------------------\n\n/// Top-level group of a product.\nenum ProductType {\n  /// Upper-body clothes: tees, hoodies, jackets. Hang on the rail.\n  TOP\n  /// Lower-body clothes: jeans, trousers, shorts. Hang on the rail.\n  BOTTOM\n  /// Shoes. Stand on the shelf.\n  FOOTWEAR\n}\n\nenum ProductCategory {\n  // TOP\n  T_SHIRT\n  SHIRT\n  SWEATSHIRT\n  HOODIE\n  KNITWEAR\n  BLAZER\n  JACKET\n  COAT\n  // BOTTOM\n  JEANS\n  TROUSERS\n  CARGO\n  JOGGERS\n  SHORTS\n  // FOOTWEAR\n  SNEAKERS\n  BOOTS\n  LOAFERS\n  SANDALS\n}\n\nenum Gender {\n  MEN\n  WOMEN\n  UNISEX\n}\n\nenum ProductStatus {\n  /// Not visible in the store.\n  DRAFT\n  /// Visible and can be bought.\n  ACTIVE\n  /// Hidden, but kept for old orders.\n  ARCHIVED\n}\n\n/// Which side of the product a photo shows. For shoes SIDE is the main photo.\n/// FOLDED: the item folded in a stack (shown on the display table; used for bottoms).\nenum ImageView {\n  FRONT\n  SIDE\n  BACK\n  FOLDED\n}\n\nmodel Product {\n  id             String          @id @default(cuid())\n  /// Human readable id used in URLs: \"green-hoodie\".\n  slug           String          @unique\n  name           String\n  description    String?\n  type           ProductType\n  category       ProductCategory\n  gender         Gender          @default(UNISEX)\n  /// Color name shown to the customer.\n  color          String\n  /// Color for swatches and filters, \"#1f3d2b\".\n  colorHex       String?\n  /// Current price. The currency is set once for the whole store (src/config/store.config.ts).\n  price          Decimal         @db.Decimal(12, 2)\n  /// Price before the discount. Set it to show the old price crossed out.\n  compareAtPrice Decimal?        @db.Decimal(12, 2)\n  status         ProductStatus   @default(DRAFT)\n  featured       Boolean         @default(false)\n  /// Lower number = earlier in lists.\n  sortOrder      Int             @default(0)\n\n  images   ProductImage[]\n  variants ProductVariant[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, type, sortOrder])\n  @@index([category])\n  @@map(\"products\")\n}\n\nmodel ProductImage {\n  id        String    @id @default(cuid())\n  productId String\n  product   Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  view      ImageView\n  /// Public path or full URL.\n  url       String\n  alt       String?\n\n  @@unique([productId, view])\n  @@map(\"product_images\")\n}\n\n/// One size of one product. The stock lives here, not in Product.\nmodel ProductVariant {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  /// \"M\", \"32\", \"42\". Valid values depend on Product.type (see SIZE_CHART).\n  size      String\n  sku       String  @unique\n  stock     Int     @default(0)\n\n  movements StockMovement[]\n\n  @@unique([productId, size])\n  @@index([productId])\n  @@map(\"product_variants\")\n}\n\n// ---------------------------------------------------------------------------\n// Warehouse\n//\n// ProductVariant.stock is the current balance. Every change of it is written\n// here too, in the same transaction, so the history always explains the balance.\n// ---------------------------------------------------------------------------\n\nenum StockMovementType {\n  /// The first balance when a product is created.\n  INITIAL\n  /// Goods arrived (delta > 0).\n  RECEIPT\n  /// The balance was counted and corrected (delta can be + or -).\n  ADJUSTMENT\n  /// Damaged, lost, given away (delta < 0).\n  WRITE_OFF\n  /// Sold to a customer (delta < 0). Used by orders.\n  SALE\n  /// Came back from a customer (delta > 0). Used by orders.\n  RETURN\n}\n\nmodel StockMovement {\n  id           String            @id @default(cuid())\n  variantId    String\n  variant      ProductVariant    @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  type         StockMovementType\n  /// Signed change: +10 for a receipt, -2 for a write-off.\n  delta        Int\n  /// The balance right after this movement.\n  balanceAfter Int\n  note         String?\n  /// Who did it (null for the seed script or after the user is deleted).\n  userId       String?\n  user         User?             @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt    DateTime          @default(now())\n\n  @@index([variantId, createdAt])\n  @@index([createdAt])\n  @@map(\"stock_movements\")\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  USER\n  /// Can open /admin: add products and manage the warehouse.\n  ADMIN\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  name         String\n  email        String   @unique\n  // null for accounts created through Google\n  passwordHash String?\n  image        String?\n  role         Role     @default(USER)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  stockMovements StockMovement[]\n\n  @@map(\"users\")\n}\n",
